import {Ajv} from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId?: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

function normalizeToolResponse(raw: string | ToolResponse): ToolResponse {
  if (typeof raw === 'string') {
    return {result: raw};
  }
  return raw;
}

interface RegisteredTool {
  definition: ToolDefinition;
  executor: ToolExecutor;
  validate: ValidateFunction;
}

export class ToolRegistry {
  private tools: Map<string, RegisteredTool> = new Map();
  private ajv = new Ajv({allErrors: true, strict: false});

  register(definition: ToolDefinition, executor: ToolExecutor): void {
    const validate = this.ajv.compile(definition.inputSchema);
    this.tools.set(definition.name, {definition, executor, validate});
    log.info('tools', `registered tool: ${definition.name}`);
  }

